infra.infra/prod/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = "{}"
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.r.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "s3:GetObject", Resource = "arn:aws:s3:::exports-prod/*" }, { Effect = "Deny", Action = "s3:GetObject", Resource = "arn:aws:s3:::*" }] })
}

